import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"2015Q3 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2015Q3 Ceph社区季度进展报告","date":"2015-09-01T00:00:00.000Z","updated":"2015-09-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/2015Q3_Ceph社区季度总结.md","filePath":"posts/2015/2015Q3_Ceph社区季度总结.md","lastUpdated":1780460162000}'),s={name:"posts/2015/2015Q3_Ceph社区季度总结.md"};function l(i,e,_,p,n,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<p>我将基于这28篇2015Q3季度的会议和视频总结，生成一份完整的社区季度进展报告。</p><hr><h1 id="ceph-社区季度进展报告-2015-q3-7月–9月" tabindex="-1">Ceph 社区季度进展报告：2015 Q3（7月–9月） <a class="header-anchor" href="#ceph-社区季度进展报告-2015-q3-7月–9月" aria-label="Permalink to &quot;Ceph 社区季度进展报告：2015 Q3（7月–9月）&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区的技术讨论呈现出以下几条主线：</p><p><strong>性能优化</strong>是贯穿全季度的核心主题。从 RADOS 层的尾延迟改进、OSD Pering 加速，到存储引擎选型（LevelDB vs RocksDB），再到内存分配器（Jemalloc vs TCMalloc）的对比测试，性能问题在多个会议中反复出现。详见 <a href="/VideoSummary/posts/2015/2015-AUG-27_--_Ceph_Tech_Talks_-_Ceph_Performance.html">2015-AUG-27 Ceph Tech Talks - Ceph Performance</a>) 和 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.html">CDS Jewel -- RADOS Tail Latency Improvements</a>)。</p><p><strong>新存储后端探索</strong>是另一条重要主线。NewStore（后演化为 BlueStore）的小对象存储优化、PMStore 实验性后端，以及 metadata-only journal mode 的算法设计，均在本季度密集讨论。</p><p><strong>RGW 多站点与多租户</strong>成为对象存储方向的重点，涵盖多站点配置模型重构、数据同步机制改进、多租户命名空间隔离等议题。</p><p><strong>CephFS 稳定化</strong>持续推进，包括 fsck/修复工具开发、IO hint 框架设计、starter tasks梳理等。</p><p><strong>安全与 QoS</strong> 也在本季度进入议程，CephX 暴力破解防护和 RADOS QoS 策略均有专项讨论。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="_2-1-存储引擎与后端" tabindex="-1">2.1 存储引擎与后端 <a class="header-anchor" href="#_2-1-存储引擎与后端" aria-label="Permalink to &quot;2.1 存储引擎与后端&quot;">​</a></h3><p><strong>NewStore 小对象优化</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Optimize_newstore_for_massive_small_object_storage.html">CDS Jewel -- Optimize newstore for massive small object storage</a>) 讨论了将多个小对象合并为 64MB 大文件（类似 TFS 实现）的方案，以减少随机 I/O，并探讨了引用计数和 PG 锁的配合机制。</p><p><strong>PMStore 实验性后端</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_PMStore.html">CDS Jewel -- PMStore</a>) 介绍了基于非易失性存储（NVM）的实验性 OSD 后端，使用内存映射文件存储对象，对象索引在内存中维护并在启动时从块元数据重建，计划开源。</p><p><strong>Metadata-only Journal Mode</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_metadata-only_journal_mode.html">CDS Jewel -- RADOS metadata-only journal mode</a>) 提出两种算法方案，核心权衡是&quot;先写数据后提交元数据日志&quot;与&quot;先提交元数据日志后写数据&quot;之间的一致性与性能取舍，计划通过仿真测试选型。</p><p><strong>存储引擎迁移</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.html">CDS Jewel -- RADOS Tail Latency Improvements</a>) 中讨论了用 RocksDB 替代 LevelDB，以解决压缩过程中的性能抖动问题。</p><h3 id="_2-2-rados-层改进" tabindex="-1">2.2 RADOS 层改进 <a class="header-anchor" href="#_2-2-rados-层改进" aria-label="Permalink to &quot;2.2 RADOS 层改进&quot;">​</a></h3><p><strong>Peering 加速</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Peering_Speed_Improvements.html">CDS Jewel -- Pering Speed Improvements</a>) 分析了 Peering 过程中多轮往返（get-info、get-log、get-missing）的开销，提出利用历史信息预测上一次 interval 正确性、缓存信息避免重复获取等优化方向。</p><p><strong>RADOS QoS</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_QoS.html">CDS Jewel -- RADOS QoS</a>) 讨论了基于 dmClock（EM 算法）的 I/O 调度器改进，支持为客户端配置最小/最大 IOPS，并探讨了 OSD 性能自动检测和网络 QoS 联动。</p><p><strong>多对象事务</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_multi-object_transaction_support.html">CDS Jewel -- RADOS multi-object transaction support</a>) 提出基于两阶段提交协议的多对象事务机制，支持客户端定义事务主体和对象操作列表，并讨论了死锁检测和超时机制。</p><p><strong>Slopy Reads</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Sloppy_Reads.html">CDS Jewel -- Sloppy Reads</a>) 探讨了允许客户端从非活动 OSD 读取数据以降低延迟的可能性，讨论了引入新存储池类型或参数来支持多种一致性级别。</p><p><strong>Scrub Repair智能化</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Scrub_Repair.html">CDS Jewel -- Scrub Repair</a>) 提出重构修复流程，支持对单个对象执行有针对性的修复，并使用 JSON 格式持久化不一致对象信息。</p><h3 id="_2-3-rgw-方向" tabindex="-1">2.3 RGW 方向 <a class="header-anchor" href="#_2-3-rgw-方向" aria-label="Permalink to &quot;2.3 RGW 方向&quot;">​</a></h3><p><strong>多站点配置模型重构</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Configuration.html">CDS Jewel -- RGW Multisite Configuration</a>) 引入了 Zone、Zone Group、Realm、Period 四层配置模型，支持运行时动态配置变更，无需重启网关。</p><p><strong>多站点同步改进</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.html">CDS Jewel -- RGW Multisite Sync</a>) 讨论了元数据同步和据同步的改进方案，引入 Active-Active 复制、推送通知机制，并计划移除独立的网关代理进程，将代理功能内嵌到网关中。</p><p><strong>多租户支持</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multitenancy.html">CDS Jewel -- RGW Multitenancy</a>) 讨论了为 RGW 引入独立租户命名空间，修改存储桶和用户标识符数据结构，并探讨了与 Keystone 租户的映射集成方案。</p><p><strong>Hadoop over RGW</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Hadoop_over_Ceph_RGW.html">CDS Jewel -- Hadoop over Ceph RGW</a>) 介绍了 Rgw Skidaway FS（Hadoop 兼容文件系统插件）的进展，已完成约 70% 代码开发，添加了块级位置信息以提升读取性能，与 HDFS 基准对比中 Swift 读取性能约低 20%。</p><h3 id="_2-4-cephfs-方向" tabindex="-1">2.4 CephFS 方向 <a class="header-anchor" href="#_2-4-cephfs-方向" aria-label="Permalink to &quot;2.4 CephFS 方向&quot;">​</a></h3><p><strong>fsck 工具进展</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephFS_fsck_progress.html">CDS Jewel -- CephFS fsck progress</a>) 介绍了数据扫描工具的两阶段设计：第一阶段扫描数据池对象并记录元数据，第二阶段利用元数据修复元数据树，并讨论了目录碎片、快照处理等边界情况。</p><p><strong>IO Hints 框架</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_add_IOHints_in_CephFS.html">CDS Jewel -- add IOHints in CephFS</a>) 讨论了通用 IO hint 框架，用于实现数据生命周期控制、数据重要性标识和分配策略，探讨了缓存数据/可用数据/非可用数据的标识体系。</p><p><strong>Starter Tasks 梳理</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephFS_starter_tasks.html">CDS Jewel -- CephFS starter tasks</a>) 整理了适合新贡献者入手的任务，包括缓存状态导出、目录碎片对象检查工具、异步接口集成、MDS 类型拆分等。</p><h3 id="_2-5-rbd-方向" tabindex="-1">2.5 RBD 方向 <a class="header-anchor" href="#_2-5-rbd-方向" aria-label="Permalink to &quot;2.5 RBD 方向&quot;">​</a></h3><p><strong>RBD Journal Blueprint</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_RBD_Journal.html">CDS Jewel -- RBD Journal</a>) 设计了基于 librados API 的通用日志机制，使用 RNG 算法将日志条目分散到多个对象，引入软最大小限制，支持多读者，为 RBD 跨数据中心镜像复制奠定基础。</p><h3 id="_2-6-安全" tabindex="-1">2.6 安全 <a class="header-anchor" href="#_2-6-安全" aria-label="Permalink to &quot;2.6 安全&quot;">​</a></h3><p><strong>CephX 暴力破解防护</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephX_brute-force_protection.html">CDS Jewel -- CephX brute-force protection</a>) 讨论了自动黑名单机制，针对频繁错误认证的客户端进行封禁，并探讨了 OSD map 签名以增强安全性。</p><h3 id="_2-7-基础设施与运维" tabindex="-1">2.7 基础设施与运维 <a class="header-anchor" href="#_2-7-基础设施与运维" aria-label="Permalink to &quot;2.7 基础设施与运维&quot;">​</a></h3><p><strong>参考架构</strong>：<a href="/VideoSummary/posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.html">2015-SEP-24 Ceph Tech Talks - Reference Architectures</a>) 发布了与 Supermicro、Cisco、Scalable Informatics 合作的性能与尺寸指南，提出 4×3 矩阵用于识别不同工作负载（IOPS 优化、吞吐量优化、成本容量优化）的候选架构。</p><p><strong>Calamari 硬件 API</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.html">CDS Jewel -- Calamari API Storage Hardware</a>) 规划了硬件 API，使 Calamari 能感知底层存储硬件状态（SMART 数据、设备序列号等），支持 SUSE、Ubuntu、CentOS，并计划扩展 Fedora 支持。</p><p><strong>Ceph on Mesos</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Ceph_Mesos.html">CDS Jewel -- Ceph Mesos</a>) 介绍了 Intel 上海团队开发的 Seth Mesos 框架，支持在 Apache Mesos 上部署和扩展 Ceph 集群（OSD、Mon、Gateway），动态伸缩和故障转移功能仍在开发中。</p><p><strong>非功能性测试框架</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Non-Functional_Tests.html">CDS Jewel -- Non-Functional Tests</a>) 提出将可扩展性、性能等非功能性测试纳入 Ceph 开发流程，使用 cgroup 资源限制控制测试环境，开发 maestro/rattles/averte 等任务组件。</p><p><strong>性能回归检测</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Ceph_0_day_for_performance_regression.html">CDS Jewel -- Ceph 0 day for performance regression</a>) 讨论了建立自动化性能回归测试框架，使用 fio 等工具进行基准测试，并将结果集成到日常 CI 流程中。</p><p><strong>消息优先级</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Messenger_Priorities_for_Client.html">CDS Jewel -- Messenger Priorities for Client</a>) 讨论了通过 Token Bucket 算法实现客户端消息优先级队列，解决负载不均衡问题。</p><p><strong>缓存层优化</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Cache_Tiering.html">CDS Jewel -- Cache Tiering</a>) 讨论了缓存穿透问题的实验方案、基于重用距离算法的驱逐策略改进，以及 Sandisk 提出的策略引擎（支持用户自定义缓存策略）。</p><p><strong>被动 Monitor</strong>：<a href="/VideoSummary/posts/2015/CDS_Jewel_--_Passive_Monitors.html">CDS Jewel -- Passive Monitors</a>) 讨论了不参与 Quorum 但接收所有提案的被动 Monitor 设计，用于增强灾难恢复能力，并分析了脑裂（Split Brain）防护机制。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><ul><li><p><strong>Jewel 版本规划启动</strong>：本季度大量 CDS（Ceph Developer Summit）Jewel 专项会议密集召开，涵盖存储引擎、RGW、CephFS、RADOS、安全等几乎所有子系统，标志着 Jewel 版本的特性规划进入实质阶段。</p></li><li><p><strong>RGW 多站点架构重构决策</strong>：确定引入 Zone/Zone Group/Realm/Period 四层模型，这是 RGW 多站点功能的重大架构升级，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Configuration.html">CDS Jewel -- RGW Multisite Configuration</a>) 和 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.html">CDS Jewel -- RGW Multisite Sync</a>)。</p></li><li><p><strong>RBD Journal 设计确定</strong>：RBD Journal Blueprint 完成设计评审，为后续 RBD 镜像（rbd-mirror）功能奠定基础，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_RBD_Journal.html">CDS Jewel -- RBD Journal</a>)。</p></li><li><p><strong>NewStore 小对象优化方向确定</strong>：决定在 NewStore 中实现小对象合并存储方案，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_Optimize_newstore_for_massive_small_object_storage.html">CDS Jewel -- Optimize newstore for massive small object storage</a>)。</p></li><li><p><strong>CephFS 进入稳定化阶段</strong>：<a href="/VideoSummary/posts/2015/2015-JUL-30_--_Ceph_Tech_Talks_-_CephFS.html">2015-JUL-30 Ceph Tech Talks - CephFS</a>) 显示 CephFS 已具备高可用性、访问控制、故障恢复工具等生产级特性，社区正在推进稳定化和 QA 工作。</p></li><li><p><strong>Jemalloc 性能优势确认</strong>：<a href="/VideoSummary/posts/2015/2015-AUG-27_--_Ceph_Tech_Talks_-_Ceph_Performance.html">2015-AUG-27 Ceph Tech Talks - Ceph Performance</a>) 中 Red Hat 测试确认 Jemalloc 在小 I/O 场景下性能显著优于 TCMalloc，但内存占用更高，需进一步权衡。</p></li></ul><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>Tech Talks 系列</strong>：本季度举办了三场面向社区的 Ceph Tech Talks，分别聚焦性能调优（8月）、CephFS（7月）和参考架构（9月），覆盖了从底层性能到上层部署的完整技术栈。</p><p><strong>CDS Jewel 开发者峰会</strong>：本季度召开了大规模的 Ceph Developer Summit，针对 Jewel 版本进行了系统性的特性规划，涉及议题超过 20 个，参与者来自 Red Hat、Intel、Sandisk、UC Santa Cruz 等机构。</p><p><strong>Intel 上海团队贡献</strong>：Intel 上海研发团队在本季度贡献了 Ceph Mesos 框架（Seth Mesos），展示了 Ceph 在容器编排平台上的集成能力，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_Ceph_Mesos.html">CDS Jewel -- Ceph Mesos</a>)。</p><p><strong>学术界参与</strong>：UC Santa Cruz 博士生（Red Hat 实习生）主导了非功能性测试框架项目，体现了学术界与工业界在 Ceph 社区的协作，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_Non-Functional_Tests.html">CDS Jewel -- Non-Functional Tests</a>)。</p><p><strong>参考架构生态建设</strong>：Red Hat 与 Supermicro、Cisco、Scalable Informatics 合作发布了多份性能与尺寸指南，并建立了社区性能基准测试库，详见 <a href="/VideoSummary/posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.html">2015-SEP-24 Ceph Tech Talks - Reference Architectures</a>)。</p><p><strong>Calamari 正式发布</strong>：Calamari 最新稳定版本在本季度发布，可通过 download.com/calamari 下载，支持 SUSE、Ubuntu、CentOS，详见 <a href="/VideoSummary/posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.html">CDS Jewel -- Calamari API Storage Hardware</a>)。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论内容，预计 2015 Q4 将重点推进以下方向：</p><ol><li><p><strong>BlueStore/NewStore 实现落地</strong>：小对象合并存储、metadata-only journal mode 的仿真测试选型完成后，将进入编码实现阶段。</p></li><li><p><strong>RBD Mirror 功能开发</strong>：RBD Journal Blueprint 设计已确定，下季度将进入代码实现，推进跨数据中心 RBD 镜像复制功能。</p></li><li><p><strong>RGW 多站点新架构上线</strong>：Zone/Zone Group/Realm/Period 模型的代码实现将是 RGW 方向的核心工作，Active-Active 复制和推送通知功能也将跟进开发。</p></li><li><p><strong>CephFS fsck 工具完善</strong>：数据扫描工具的两阶段实现将继续推进，目录碎片和快照处理等边界情况需要解决。</p></li><li><p><strong>RADOS QoS 原型验证</strong>：基于 dmClock 的 I/O 调度器改进方案将进入原型开发和测试阶段。</p></li><li><p><strong>性能回归 CI 集成</strong>：自动化性能回归测试框架将逐步集成到 Ceph 日常 CI 流程中，以防止性能退化。</p></li><li><p><strong>CephX 安全加固</strong>：自动黑名单机制和 OSD map 签名功能将进入实现阶段。</p></li><li><p><strong>Hadoop over RGW 开源</strong>：Rgw Skidaway FS 代码开发接近完成，预计下季度完成基准测试并开源。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2015/2015-AUG-27_--_Ceph_Tech_Talks_-_Ceph_Performance.html">2015-AUG-27 -- Ceph Tech Talks: Ceph Performance</a>)</li><li><a href="/VideoSummary/posts/2015/2015-JUL-30_--_Ceph_Tech_Talks_-_CephFS.html">2015-JUL-30 -- Ceph Tech Talks: CephFS</a>)</li><li><a href="/VideoSummary/posts/2015/2015-SEP-24_--_Ceph_Tech_Talks_-_Reference_Architectures.html">2015-SEP-24 -- Ceph Tech Talks: Reference Architectures</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Cache_Tiering.html">CDS Jewel -- Cache Tiering</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Calamari_API_Storage_Hardware.html">CDS Jewel -- Calamari/API/Storage/Hardware</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephFS_fsck_progress.html">CDS Jewel -- CephFS fsck progress</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephFS_starter_tasks.html">CDS Jewel -- CephFS starter tasks</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_CephX_brute-force_protection.html">CDS Jewel -- CephX brute-force protection</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Ceph_0_day_for_performance_regression.html">CDS Jewel -- Ceph 0 day for performance regression</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Ceph_Mesos.html">CDS Jewel -- Ceph Mesos</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Hadoop_over_Ceph_RGW.html">CDS Jewel -- Hadoop over Ceph RGW</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Messenger_Priorities_for_Client.html">CDS Jewel -- Messenger, Priorities for Client</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Non-Functional_Tests.html">CDS Jewel -- Non-Functional Tests</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Optimize_newstore_for_massive_small_object_storage.html">CDS Jewel -- Optimize newstore for massive small object storage</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_PMStore.html">CDS Jewel -- PMStore</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Passive_Monitors.html">CDS Jewel -- Passive Monitors</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Peering_Speed_Improvements.html">CDS Jewel -- Peering Speed Improvements</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_QoS.html">CDS Jewel -- RADOS QoS</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_Tail_Latency_Improvements.html">CDS Jewel -- RADOS Tail Latency Improvements</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_metadata-only_journal_mode.html">CDS Jewel -- RADOS metadata-only journal mode</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RADOS_multi-object_transaction_support.html">CDS Jewel -- RADOS multi-object transaction support</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RBD_Journal.html">CDS Jewel -- RBD Journal</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Configuration.html">CDS Jewel -- RGW Multisite Configuration</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multisite_Sync.html">CDS Jewel -- RGW Multisite Sync</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_RGW_Multitenancy.html">CDS Jewel -- RGW Multitenancy</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Scrub_Repair.html">CDS Jewel -- Scrub Repair</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_Sloppy_Reads.html">CDS Jewel -- Sloppy Reads</a>)</li><li><a href="/VideoSummary/posts/2015/CDS_Jewel_--_add_IOHints_in_CephFS.html">CDS Jewel -- add IOHints in CephFS</a>)</li></ul>',64)])])}const C=a(s,[["render",l]]);export{m as __pageData,C as default};
